  const B1S = [
    { en: 'In other words, the plan is to sell the house.', es: 'Es decir, el plan es vender la casa.', ans: ['Es', 'decir', 'el', 'plan', 'es', 'vender', 'la', 'casa'], distr: ['o', 'se', 'vender'], explain: '<b>Es decir</b> = "in other words" — a classic B1 connective for reformulating.' },
    { en: 'I don\'t think I can come on Friday.', es: 'No creo que pueda venir el viernes.', ans: ['No', 'creo', 'que', 'pueda', 'venir', 'el', 'viernes'], distr: ['puedo', 'creo', 'viernes'], explain: 'Doubt (no creo que) → <b>subjunctive</b>: <i>pueda</i>, not <i>puedo</i>.' },
    { en: 'The truth is, I was going to tell you.', es: 'La verdad es que iba a contártelo.', ans: ['La', 'verdad', 'es', 'que', 'iba', 'a', 'contártelo'], distr: ['voy', 'digo', 'todavía'], explain: 'Past intention: <b>iba a</b> + infinitive. <i>Contártelo</i> = to tell it to you.' },
    { en: 'To be honest, I miss my family a lot.', es: 'Para ser honesto, echo de menos a mi familia.', ans: ['Para', 'ser', 'honesto', 'echo', 'de', 'menos', 'a', 'mi', 'familia'], distr: ['mí', 'es', 'mi'], explain: '<b>Echar de menos</b> = to miss. It takes <i>a</i> before a person: <i>echo de menos a mi familia</i>.' },
    { en: 'It was a mistake. I regret saying that.', es: 'Fue un error. Me arrepiento de haberlo dicho.', ans: ['Fue', 'un', 'error', 'Me', 'arrepiento', 'de', 'haberlo', 'dicho'], distr: ['dije', 'arrepentido', 'decir'], explain: '<b>Arrepentirse de + haber + participle</b> for past regrets.' },
    { en: 'I\'m sure he is at home.', es: 'Estoy seguro de que está en casa.', ans: ['Estoy', 'seguro', 'de', 'que', 'está', 'en', 'casa'], distr: ['soy', 'de', 'está'], explain: 'Certainty (estoy seguro de que) → <b>indicative</b>: <i>está</i>.' },
    { en: 'Anyway, I\'m not going to argue about it.', es: 'De todos modos, no voy a discutir sobre eso.', ans: ['De', 'todos', 'modos', 'no', 'voy', 'a', 'discutir', 'sobre', 'eso'], distr: ['pues', 'no', 'discuto'], explain: '<b>De todos modos</b> = "anyway". <i>No voy a + infinitive</i> for a present decision.' },
    { en: 'At this point, there\'s nothing to be done.', es: 'A estas alturas, no hay nada que hacer.', ans: ['A', 'estas', 'alturas', 'no', 'hay', 'nada', 'que', 'hacer'], distr: ['ahora', 'hay', 'nada'], explain: '<b>A estas alturas</b> = "at this point / by now".' },
    { en: 'In any case, I didn\'t break the window.', es: 'De todos modos, no rompí la ventana.', ans: ['De', 'todos', 'modos', 'no', 'rompí', 'la', 'ventana'], distr: ['romper', 'rota', 'rompiste'], explain: 'Finished past action → <b>preterite</b>: <i>rompí</i>.' },
    { en: 'My boss is giving me a hard time.', es: 'Mi jefe me está dando un mal rato.', ans: ['Mi', 'jefe', 'me', 'está', 'dando', 'un', 'mal', 'rato'], distr: ['jefe', 'está', 'ratón'], explain: '<b>Dar un mal rato</b> = to make things unpleasant (idiom).' },
    { en: 'The rent doesn\'t include internet.', es: 'La renta no incluye internet.', ans: ['La', 'renta', 'no', 'incluye', 'internet'], distr: ['no', 'incluyo', 'internet'], explain: '<b>Renta</b> = rent (Mexican). "It doesn\'t include" = <i>no incluye</i>.' },
    { en: 'I\'m going to rent an apartment downtown.', es: 'Voy a arrendar un apartamento en el centro.', ans: ['Voy', 'a', 'arrendar', 'un', 'apartamento', 'en', 'el', 'centro'], distr: ['alquilo', 'vivo', 'centro'], explain: '<b>Arrendar</b> = to rent (Mexican) — the everyday word in Mexico.' },
    { en: 'This restaurant is worth a detour.', es: 'Este restaurante vale la pena.', ans: ['Este', 'restaurante', 'vale', 'la', 'pena'], distr: ['cobra', 'cuesta', 'premio'], explain: '<b>Vale la pena</b> = "it\'s worth it".' },
    { en: 'I have a meeting at ten in the morning.', es: 'Tengo una reunión a las diez de la mañana.', ans: ['Tengo', 'una', 'reunión', 'a', 'las', 'diez', 'de', 'la', 'mañana'], distr: ['tienes', 'once', 'hora'], explain: 'Time: <b>a las diez de la mañana</b>.' },
    { en: 'I\'ll pay off the debt next year.', es: 'Voy a pagar la deuda el año que viene.', ans: ['Voy', 'a', 'pagar', 'la', 'deuda', 'el', 'año', 'que', 'viene'], distr: ['pagué', 'pagaré', 'pronto'], explain: '<b>El año que viene</b> = next year.' },
    { en: 'You have to be more punctual.', es: 'Tienes que ser más puntual.', ans: ['Tienes', 'que', 'ser', 'más', 'puntual'], distr: ['tengo', 'que', 'punctual'], explain: '<b>Tener que + infinitive</b> = to have to.' },
    // — new B1 sentences (subjunctive, relatives, conditionals, discourse) —
    { en: 'I am worried that the appointment will be postponed.', es: 'Me preocupa que la cita se posponga.', ans: ['Me', 'preocupa', 'que', 'la', 'cita', 'se', 'posponga'], distr: ['preocupo', 'pospone', 'cita'], explain: 'Emotion + que → <b>subjunctive</b>: <i>me preocupa que… se posponga</i>.' },
    { en: 'He left so he wouldn\'t be late for the meeting.', es: 'Se fue para no llegar tarde a la reunión.', ans: ['Se', 'fue', 'para', 'no', 'llegar', 'tarde', 'a', 'la', 'reunión'], distr: ['por', 'llegó', 'tardes'], explain: '<b>Para + (no) + infinitive</b> = in order to (not).' },
    { en: 'We will wait until he finishes his report.', es: 'Esperaremos hasta que termine su informe.', ans: ['Esperaremos', 'hasta', 'que', 'termine', 'su', 'informe'], distr: ['termina', 'terminará', 'su'], explain: 'Time clause about the future → <b>subjunctive</b>: <i>hasta que termine</i>.' },
    { en: 'It is important that everyone speaks Spanish.', es: 'Es importante que todos hablen español.', ans: ['Es', 'importante', 'que', 'todos', 'hablen', 'español'], distr: ['hablan', 'hablaremos', 'todo'], explain: 'Impersonal value judgement + que → <b>subjunctive</b>: <i>que todos hablen</i>.' },
    { en: 'I don\'t know where the office is.', es: 'No sé dónde está la oficina.', ans: ['No', 'sé', 'dónde', 'está', 'la', 'oficina'], distr: ['sé', 'era', 'trabajo'], explain: 'Indefinite where → <b>dónde</b> (with accent).' },
    { en: 'Tell me what happened yesterday.', es: 'Cuéntame qué pasó ayer.', ans: ['Cuéntame', 'qué', 'pasó', 'ayer'], distr: ['pasa', 'cuenta', 'hoy'], explain: 'Indefinite what → <b>qué</b> (with accent); preterite <i>pasó</i>.' },
    { en: 'The building where I live is very old.', es: 'El edificio donde vivo es muy viejo.', ans: ['El', 'edificio', 'donde', 'vivo', 'es', 'muy', 'viejo'], distr: ['al', 'que', 'vive'], explain: 'Relative <b>donde</b> for places: <i>el edificio donde vivo</i>.' },
    { en: 'She is the colleague who always helps.', es: 'Es la colega que siempre ayuda.', ans: ['Es', 'la', 'colega', 'que', 'siempre', 'ayuda'], distr: ['quien', 'ayudó', 'jefe'], explain: 'Relative <b>que</b> for people and things alike.' },
    { en: 'If it had rained, we would have stayed inside.', es: 'Si hubiera llovido, nos habríamos quedado dentro.', ans: ['Si', 'hubiera', 'llovido', 'nos', 'habríamos', 'quedado', 'dentro'], distr: ['llovería', 'estamos', 'llovía'], explain: 'Past unreal: <b>si hubiera + participle</b> → <b>habríamos + participle</b>.' },
    { en: 'I would have called you if I had known.', es: 'Te habría llamado si lo hubiera sabido.', ans: ['Te', 'habría', 'llamado', 'si', 'lo', 'hubiera', 'sabido'], distr: ['llamaré', 'hubieras', 'saber'], explain: 'Conditional perfect: <b>habría llamado</b> + <b>si lo hubiera sabido</b>.' },
    { en: 'It is the first time I have eaten at this restaurant.', es: 'Es la primera vez que como en este restaurante.', ans: ['Es', 'la', 'primera', 'vez', 'que', 'como', 'en', 'este', 'restaurante'], distr: ['comí', 'primer', 'ocasión'], explain: '<b>La primera vez que…</b> + present for "have eaten".' },
    { en: 'Before you leave, please lock the door.', es: 'Antes de que te vayas, cierra la puerta, por favor.', ans: ['Antes', 'de', 'que', 'te', 'vayas', 'cierra', 'la', 'puerta', 'por', 'favor'], distr: ['vas', 'cerrar', 'después'], explain: '<b>Antes de que + subjunctive</b>: <i>antes de que te vayas</i>.' },
    { en: 'The news that she passed the exam was great.', es: 'La noticia de que aprobó el examen fue genial.', ans: ['La', 'noticia', 'de', 'que', 'aprobó', 'el', 'examen', 'fue', 'genial'], distr: ['aprueba', 'mala', 'sin'], explain: 'Reported fact → <b>de que + indicative</b>: <i>de que aprobó</i>.' },
    { en: 'I am sure that you can do it.', es: 'Estoy seguro de que puedes hacerlo.', ans: ['Estoy', 'seguro', 'de', 'que', 'puedes', 'hacerlo'], distr: ['cierto', 'podrás', 'hacerla'], explain: 'Certainty → indicative: <i>de que puedes hacerlo</i>.' },
    { en: 'The more you practice, the faster you will speak.', es: 'Cuanto más practiques, más rápido hablarás.', ans: ['Cuanto', 'más', 'practiques', 'más', 'rápido', 'hablarás'], distr: ['practico', 'despacio', 'hablas'], explain: '<b>Cuanto + comparative… + más…</b> — a B1/B2 comparison structure.' },
    { en: 'As soon as I arrived, it started to rain.', es: 'En cuanto llegué, empezó a llover.', ans: ['En', 'cuanto', 'llegué', 'empezó', 'a', 'llover'], distr: ['mientras', 'empezó', 'llovía'], explain: '<b>En cuanto</b> = as soon as (a fact → indicative).' },
    { en: 'You should have told me earlier.', es: 'Deberías habérmelo dicho antes.', ans: ['Deberías', 'habérmelo', 'dicho', 'antes'], distr: ['dije', 'debería', 'ahora'], explain: '<b>Deberías + haber + participle</b> = you should have (past regret).' },
    { en: 'I would like there to be a bus to the center.', es: 'Me gustaría que hubiera un autobús al centro.', ans: ['Me', 'gustaría', 'que', 'hubiera', 'un', 'autobús', 'al', 'centro'], distr: ['hay', 'gustaba', 'tren'], explain: '<b>Me gustaría que + subjunctive</b> for a wish: <i>que hubiera</i>.' },
    { en: 'As long as you work, I am happy.', es: 'Mientras tú trabajes, yo estoy contento.', ans: ['Mientras', 'tú', 'trabajes', 'yo', 'estoy', 'contento'], distr: ['trabajas', 'estaba', 'aunque'], explain: 'Open future → <b>mientras + subjunctive</b>: <i>trabajes</i>.' },
    { en: 'The way in which he explained it was perfect.', es: 'La manera en que lo explicó fue perfecta.', ans: ['La', 'manera', 'en', 'que', 'lo', 'explicó', 'fue', 'perfecta'], distr: ['explica', 'mala', 'modo'], explain: 'Relative <b>en que</b> after a noun: <i>la manera en que…</i>.' },
    { en: 'He pretended to sleep so he wouldn\'t answer.', es: 'Hizo como que dormía para no contestar.', ans: ['Hizo', 'como', 'que', 'dormía', 'para', 'no', 'contestar'], distr: ['hace', 'dormir', 'responder'], explain: '<b>Hacer como que + imperfect</b> = to pretend (ongoing action).' },
    { en: 'There is no way that I will accept this proposal.', es: 'No hay manera de que acepte esta propuesta.', ans: ['No', 'hay', 'manera', 'de', 'que', 'acepte', 'esta', 'propuesta'], distr: ['acepto', 'habrá', 'forma'], explain: 'Impossibility → <b>no hay manera de que + subjunctive</b>.' },
    { en: 'I was about to leave when the phone rang.', es: 'Iba a salir cuando sonó el teléfono.', ans: ['Iba', 'a', 'salir', 'cuando', 'sonó', 'el', 'teléfono'], distr: ['salí', 'sona', 'voy'], explain: '<b>Iba a + infinitive</b> interrupted by an event in the preterite.' },
    { en: 'Everyone agrees that the results are good.', es: 'Todos coinciden en que los resultados son buenos.', ans: ['Todos', 'coinciden', 'en', 'que', 'los', 'resultados', 'son', 'buenos'], distr: ['coincide', 'malos', 'con'], explain: 'Agreement about a fact → <b>coinciden en que + indicative</b>.' },
    { en: 'It is not worth arguing about nothing.', es: 'No vale la pena discutir por nada.', ans: ['No', 'vale', 'la', 'pena', 'discutir', 'por', 'nada'], distr: ['discutió', 'tiempo', 'algo'], explain: '<b>No vale la pena + infinitive</b> = it\'s not worth it.' },
    { en: 'I would not have believed it if it had been me.', es: 'No lo habría creído si hubiera sido yo.', ans: ['No', 'lo', 'habría', 'creído', 'si', 'hubiera', 'sido', 'yo'], distr: ['creeré', 'fue', 'creo'], explain: 'Double past-unreal: <b>habría creído… si hubiera sido</b>.' },
    { en: 'Let us take a break before we continue.', es: 'Tomen un descanso antes de que sigamos.', ans: ['Tomen', 'un', 'descanso', 'antes', 'de', 'que', 'sigamos'], distr: ['sigues', 'tomar', 'después'], explain: 'Command + <b>antes de que + subjunctive</b>: <i>antes de que sigamos</i>.' },
    { en: 'The problem is that we do not have time.', es: 'El problema es que no tenemos tiempo.', ans: ['El', 'problema', 'es', 'que', 'no', 'tenemos', 'tiempo'], distr: ['somos', 'teníamos', 'estamos'], explain: 'Statement of fact → <b>es que + indicative</b>.' },
    { en: 'He is someone you can trust.', es: 'Es una persona en quien puedes confiar.', ans: ['Es', 'una', 'persona', 'en', 'quien', 'puedes', 'confiar'], distr: ['que', 'confiarás', 'con'], explain: 'When the relative needs a preposition + person: <b>en quien</b>.' },
    { en: 'When it comes to cooking, I am hopeless.', es: 'Cuando se trata de cocinar, soy un desastre.', ans: ['Cuando', 'se', 'trata', 'de', 'cocinar', 'soy', 'un', 'desastre'], distr: ['trato', 'eres', 'experto'], explain: '<b>Cuando se trata de</b> = when it comes to.' },
    { en: 'The company I work for is very fair.', es: 'La empresa para la que trabajo es muy justa.', ans: ['La', 'empresa', 'para', 'la', 'que', 'trabajo', 'es', 'muy', 'justa'], distr: ['donde', 'injusta', 'con'], explain: 'Preposition + relative pronoun: <b>para la que</b> (feminine) = "for which".' },
    { en: 'I would rather not talk about it right now.', es: 'Prefiero no hablar de ello ahora mismo.', ans: ['Prefiero', 'no', 'hablar', 'de', 'ello', 'ahora', 'mismo'], distr: ['hablaré', 'eso', 'ya'], explain: '<b>Preferir + infinitive</b>; <i>ahora mismo</i> = right now.' },
    { en: 'It is the kind of music I love.', es: 'Es el tipo de música que adoro.', ans: ['Es', 'el', 'tipo', 'de', 'música', 'que', 'adoro'], distr: ['desprecio', 'película', 'estilo'], explain: 'Relative <b>que</b> after <i>el tipo de…</i>.' },
    { en: 'As soon as I get the money, I will pay you back.', es: 'En cuanto tenga el dinero, te lo devolveré.', ans: ['En', 'cuanto', 'tenga', 'el', 'dinero', 'te', 'lo', 'devolveré'], distr: ['tengo', 'devolví', 'cuando'], explain: 'Future reference → <b>en cuanto + subjunctive</b>: <i>tenga</i>.' },
    { en: 'I suspect that he is hiding something.', es: 'Sospecho que algo oculta.', ans: ['Sospecho', 'que', 'algo', 'oculta'], distr: ['ocultó', 'sospeché', 'nada'], explain: 'Doubt verb → <b>sospecho que + subjunctive</b> (word order is free here).' },
    { en: 'There are still things I do not understand.', es: 'Todavía hay cosas que no entiendo.', ans: ['Todavía', 'hay', 'cosas', 'que', 'no', 'entiendo'], distr: ['entendí', 'está', 'ya'], explain: 'Open/indefinite antecedent + relative: <b>cosas que…</b>.' },
    { en: 'If I were you, I would talk to him.', es: 'Si yo fuera tú, hablaría con él.', ans: ['Si', 'yo', 'fuera', 'tú', 'hablaría', 'con', 'él'], distr: ['fui', 'hablo', 'sería'], explain: 'Hypothetical advice: <b>si fuera</b> (subjunctive) + <b>hablaría</b> (conditional).' },
    { en: 'The less you eat, the lighter you feel.', es: 'Cuanto menos comes, más ligero te sientes.', ans: ['Cuanto', 'menos', 'comes', 'más', 'ligero', 'te', 'sientes'], distr: ['comiste', 'pesado', 'menos'], explain: 'Parallel comparison: <b>cuanto menos… más…</b>' },
    { en: 'I don\'t remember when I bought it.', es: 'No recuerdo cuándo lo compré.', ans: ['No', 'recuerdo', 'cuándo', 'lo', 'compré'], distr: ['compro', 'olvido', 'donde'], explain: 'Indefinite when → <b>cuándo</b> (with accent).' },
    { en: 'She asked me if I wanted to come.', es: 'Me preguntó si quería venir.', ans: ['Me', 'preguntó', 'si', 'quería', 'venir'], distr: ['quiero', 'pregunté', 'que'], explain: 'Reported question: <b>si + past tense</b> (no inversion in Spanish).' },
    { en: 'You don\'t understand it until you live there.', es: 'No se entiende hasta que se vive allí.', ans: ['No', 'se', 'entiende', 'hasta', 'que', 'se', 'vive', 'allí'], distr: ['entiendo', 'vivo', 'aquí'], explain: 'Impersonal <b>se</b> + <i>hasta que</i> for general truths.' },
    { en: 'I would appreciate it if you could call me.', es: 'Te lo agradecería si pudieras llamarme.', ans: ['Te', 'lo', 'agradecería', 'si', 'pudieras', 'llamarme'], distr: ['agradezco', 'puedes', 'llamarlo'], explain: 'Polite: <b>agradecería… si pudieras</b> (conditional + imperfect subjunctive).' },
    { en: 'Everyone has their own way of doing things.', es: 'Cada quien tiene su manera de hacer las cosas.', ans: ['Cada', 'quien', 'tiene', 'su', 'manera', 'de', 'hacer', 'las', 'cosas'], distr: ['todos', 'tenemos', 'forma'], explain: '<b>Cada quien… su…</b> = everyone has their own…' },
    { en: 'The more I think about it, the more I doubt.', es: 'Cuanto más lo pienso, más dudo.', ans: ['Cuanto', 'más', 'lo', 'pienso', 'más', 'dudo'], distr: ['pensé', 'dudé', 'menos'], explain: 'Self-parallel <b>cuanto más… más…</b>.' },
    { en: 'I would have liked there to be more seats.', es: 'Me habría gustado que hubiera más asientos.', ans: ['Me', 'habría', 'gustado', 'que', 'hubiera', 'más', 'asientos'], distr: ['gustó', 'había', 'sitios'], explain: 'Past wish: <b>habría gustado que + imperfect subjunctive</b>.' },
    { en: 'He is the one who is responsible for this.', es: 'Es él quien es responsable de esto.', ans: ['Es', 'él', 'quien', 'es', 'responsable', 'de', 'esto'], distr: ['que', 'culpable', 'eso'], explain: 'Emphatic: <b>es él quien…</b> = "it is he who…"' },
    { en: 'It depends on how much you earn.', es: 'Depende de cuánto ganes.', ans: ['Depende', 'de', 'cuánto', 'ganes'], distr: ['ganas', 'dependí', 'cómo'], explain: 'Open amount → <b>de cuánto + subjunctive</b>.' },
    { en: 'In order to pass, you have to practice every day.', es: 'Para aprobar, tienes que practicar todos los días.', ans: ['Para', 'aprobar', 'tienes', 'que', 'practicar', 'todos', 'los', 'días'], distr: ['por', 'practiqué', 'semanas'], explain: '<b>Para + infinitive</b> = in order to.' },
    { en: 'I do not like the way he treats people.', es: 'No me gusta cómo trata a la gente.', ans: ['No', 'me', 'gusta', 'cómo', 'trata', 'a', 'la', 'gente'], distr: ['tratando', 'agrada', 'cuándo'], explain: 'Indefinite how → <b>cómo</b>; gustar + singular subject.' },
    { en: 'I will go as long as you come with me.', es: 'Iré siempre que vengas conmigo.', ans: ['Iré', 'siempre', 'que', 'vengas', 'conmigo'], distr: ['voy', 'nunca', 'vienes'], explain: '<b>Siempre que + subjunctive</b> = as long as (future condition).' },
    { en: 'The earlier, the better.', es: 'A cuanto antes, mejor.', ans: ['A', 'cuanto', 'antes', 'mejor'], distr: ['tarde', 'mientras', 'peor'], explain: 'Fixed pattern: <b>a cuanto antes, mejor</b>.' },
    { en: 'I cannot stand it when people shout.', es: 'No soporto que la gente grite.', ans: ['No', 'soporto', 'que', 'la', 'gente', 'grite'], distr: ['grita', 'soporté', 'gritar'], explain: 'Intolerance → <b>no soporto que + subjunctive</b>.' },
    { en: 'It is necessary that everyone signs.', es: 'Es necesario que todos firmen.', ans: ['Es', 'necesario', 'que', 'todos', 'firmen'], distr: ['firman', 'importante', 'alguien'], explain: 'Necessity → <b>es necesario que + subjunctive</b>.' },
    { en: 'I will not believe it until I see it.', es: 'No lo creeré hasta que lo vea.', ans: ['No', 'lo', 'creeré', 'hasta', 'que', 'lo', 'vea'], distr: ['creo', 'vi', 'veré'], explain: 'Future reference → <b>hasta que + subjunctive</b>.' },
    { en: 'If it had not been for you, I would have failed.', es: 'Si no hubiera sido por ti, habría fracasado.', ans: ['Si', 'no', 'hubiera', 'sido', 'por', 'ti', 'habría', 'fracasado'], distr: ['fue', 'fracasé', 'ser'], explain: 'Past-unreal: <b>si no hubiera sido por… + habría + participle</b>.' },
    { en: 'The only thing I ask is respect.', es: 'Lo único que pido es respeto.', ans: ['Lo', 'único', 'que', 'pido', 'es', 'respeto'], distr: ['pide', 'única', 'dinero'], explain: '<b>Lo único que…</b> = the only thing that…' },
    { en: 'He will leave on the first bus.', es: 'Se irá en el primer autobús.', ans: ['Se', 'irá', 'en', 'el', 'primer', 'autobús'], distr: ['iré', 'último', 'tren'], explain: 'Future: <b>se irá</b> (irse = to leave).' },
    { en: 'We hardly have time to eat.', es: 'Apenas tenemos tiempo para comer.', ans: ['Apenas', 'tenemos', 'tiempo', 'para', 'comer'], distr: ['teníamos', 'siempre', 'beber'], explain: '<b>Apenas</b> = barely / hardly.' },
    { en: 'I would never have done it.', es: 'Jamás lo habría hecho.', ans: ['Jamás', 'lo', 'habría', 'hecho'], distr: ['hice', 'siempre', 'hacer'], explain: 'Strong denial: <b>jamás + habría + participle</b>.' },
    { en: 'The moment you try, you will see.', es: 'En cuanto lo intentes, lo verás.', ans: ['En', 'cuanto', 'lo', 'intentes', 'lo', 'verás'], distr: ['intentas', 'intenté', 'ves'], explain: 'Future reference → <b>en cuanto + subjunctive</b>.' },
    { en: 'I do not know who told him.', es: 'No sé quién se lo dijo.', ans: ['No', 'sé', 'quién', 'se', 'lo', 'dijo'], distr: ['digo', 'qué', 'decir'], explain: 'Indefinite who (subject) → <b>quién</b> (with accent).' },
    { en: 'It is the worst day of my life.', es: 'Es el peor día de mi vida.', ans: ['Es', 'el', 'peor', 'día', 'de', 'mi', 'vida'], distr: ['mal', 'semana', 'vida'], explain: 'Superlative: <b>el peor día de mi vida</b>.' },
    { en: 'Whatever you do, do it well.', es: 'Cualquier cosa que hagas, hazla bien.', ans: ['Cualquier', 'cosa', 'que', 'hagas', 'hazla', 'bien'], distr: ['hago', 'mal', 'vez'], explain: '<b>Cualquier cosa que + subjunctive</b> = whatever…' },
    { en: 'I wish I had more patience.', es: 'Ojalá tuviera más paciencia.', ans: ['Ojalá', 'tuviera', 'más', 'paciencia'], distr: ['tengo', 'espero', 'tiempo'], explain: '<b>Ojalá + imperfect subjunctive</b> = I wish that…' },
    { en: 'The truth is that I am tired of arguing.', es: 'La verdad es que estoy cansado de discutir.', ans: ['La', 'verdad', 'es', 'que', 'estoy', 'cansado', 'de', 'discutir'], distr: ['discutí', 'estaba', 'hecho'], explain: '<b>Estar cansado de + infinitive</b> = to be tired of…' },
    { en: 'It is not easy to find a good apartment.', es: 'No es fácil encontrar un buen apartamento.', ans: ['No', 'es', 'fácil', 'encontrar', 'un', 'buen', 'apartamento'], distr: ['encuentro', 'difícil', 'malo'], explain: '<b>Es fácil + infinitive</b>; <i>buen</i> drops the n before a masculine noun.' },
    // — full-course expansion: everyday domains in B1 structures —
    { en: 'I am trying on a jacket.', es: 'Me estoy probando una chaqueta.', ans: ['Me', 'estoy', 'probando', 'una', 'chaqueta'], distr: ['probé', 'pruebo', 'abrigo'], explain: '<b>Probarse</b> = to try on; progressive <i>me estoy probando</i>.' },
    { en: 'Your shirt looks beautiful on her.', es: 'Tu camisa le queda muy bien.', ans: ['Tu', 'camisa', 'le', 'queda', 'muy', 'bien'], distr: ['quedó', 'la', 'estupenda'], explain: 'Clothing "fits": <b>quedarse bien a alguien</b> (le queda bien).' },
    { en: 'I need a bigger size.', es: 'Necesito una talla más grande.', ans: ['Necesito', 'una', 'talla', 'más', 'grande'], distr: ['necesité', 'pequeña', 'medida'], explain: '<b>La talla</b> = size (clothes); <i>más grande</i>.' },
    { en: 'He always wears jeans on the weekend.', es: 'Él siempre usa jeans en el fin de semana.', ans: ['Él', 'siempre', 'usa', 'jeans', 'en', 'el', 'fin', 'de', 'semana'], distr: ['lunes', 'viste', 'nunca'], explain: 'Frequency word order: subject + <b>siempre</b> + verb.' },
    { en: 'Do you have this dress in black?', es: '¿Tienen este vestido en negro?', ans: ['Tienen', 'este', 'vestido', 'en', 'negro'], distr: ['venden', 'ropa', 'blanco'], explain: 'Polite "do you have": <b>¿Tienen…?</b> (ustedes form).' },
    { en: 'I am going to buy new shoes for the wedding.', es: 'Voy a comprar unos zapatos nuevos para la boda.', ans: ['Voy', 'a', 'comprar', 'unos', 'zapatos', 'nuevos', 'para', 'la', 'boda'], distr: ['compré', 'viejos', 'fiesta'], explain: '<b>Voy a + infinitive</b> for a near plan.' },
    { en: 'Where can I buy a belt?', es: '¿Dónde puedo comprar un cinturón?', ans: ['Dónde', 'puedo', 'comprar', 'un', 'cinturón'], distr: ['cuándo', 'podía', 'corbata'], explain: '<b>¿Dónde puedo + infinitive?</b> = where can I…' },
    { en: 'The suit is a bit tight.', es: 'El traje me queda un poco apretado.', ans: ['El', 'traje', 'me', 'queda', 'un', 'poco', 'apretado'], distr: ['quedó', 'ancha', 'grande'], explain: '<b>Un poco + adjective</b> = a bit…; <i>apretado</i> = tight.' },
    { en: 'My knee hurts a lot after running.', es: 'Me duele mucho la rodilla después de correr.', ans: ['Me', 'duele', 'mucho', 'la', 'rodilla', 'después', 'de', 'correr'], distr: ['dolió', 'caminar', 'codo'], explain: 'Body pain: <b>doler</b> (the body part is the subject).' },
    { en: 'She cut her finger with a knife.', es: 'Se cortó el dedo con un cuchillo.', ans: ['Se', 'cortó', 'el', 'dedo', 'con', 'un', 'cuchillo'], distr: ['cortaba', 'mano', 'tijera'], explain: 'Reflexive for body parts: <b>se cortó el dedo</b>.' },
    { en: 'He has a sore throat and a fever.', es: 'Tiene dolor de garganta y fiebre.', ans: ['Tiene', 'dolor', 'de', 'garganta', 'y', 'fiebre'], distr: ['tenía', 'tos', 'cabeza'], explain: '<b>Dolor de + body part</b>; <i>fiebre</i> = fever.' },
    { en: 'The nurse took my temperature.', es: 'La enfermera me tomó la temperatura.', ans: ['La', 'enfermera', 'me', 'tomó', 'la', 'temperatura'], distr: ['midió', 'doctor', 'termómetro'], explain: '<b>Tomar la temperatura</b> = to take a temperature.' },
    { en: 'I twisted my ankle on the stairs.', es: 'Me torcí el tobillo en la escalera.', ans: ['Me', 'torcí', 'el', 'tobillo', 'en', 'la', 'escalera'], distr: ['torcía', 'pies', 'acera'], explain: 'Reflexive: <b>me torcí el tobillo</b> (preterite: it happened once).' },
    { en: 'Your eyes are very brown.', es: 'Tus ojos son muy morenos.', ans: ['Tus', 'ojos', 'son', 'muy', 'morenos'], distr: ['es', 'azules', 'pequeños'], explain: 'Permanent quality → <b>ser</b>: <i>son morenos</i>.' },
    { en: 'The doctor pressed my chest.', es: 'El médico me presionó el pecho.', ans: ['El', 'médico', 'me', 'presionó', 'el', 'pecho'], distr: ['tocó', 'panza', 'espalda'], explain: '<b>Presionar</b> = to press; direct object after the verb.' },
    { en: 'She is washing her hair right now.', es: 'Se está lavando el pelo ahora mismo.', ans: ['Se', 'está', 'lavando', 'el', 'pelo', 'ahora', 'mismo'], distr: ['lavaba', 'cara', 'ya'], explain: 'Reflexive progressive: <b>se está lavando</b>.' },
    { en: 'It is going to rain this afternoon.', es: 'Va a llover esta tarde.', ans: ['Va', 'a', 'llover', 'esta', 'tarde'], distr: ['llueve', 'mañana', 'nieve'], explain: '<b>Va a + infinitive</b> = it\'s going to…' },
    { en: 'There is a lot of humidity in this city.', es: 'Hay mucha humedad en esta ciudad.', ans: ['Hay', 'mucha', 'humedad', 'en', 'esta', 'ciudad'], distr: ['está', 'seca', 'pueblo'], explain: '<b>Hay</b> = there is (existential, never <i>está</i> for "there is a lot of").' },
    { en: 'The storm started at midnight.', es: 'La tormenta empezó a la medianoche.', ans: ['La', 'tormenta', 'empezó', 'a', 'la', 'medianoche'], distr: ['terminó', 'amanecer', 'trueno'], explain: 'Time of a finished event → preterite: <i>empezó</i>.' },
    { en: 'It is colder today than yesterday.', es: 'Hace más frío hoy que ayer.', ans: ['Hace', 'más', 'frío', 'hoy', 'que', 'ayer'], distr: ['calor', 'mañana', 'menos'], explain: 'Weather with <b>hacer</b>: hace + más frío (impersonal).' },
    { en: 'I love sunny days.', es: 'Me encantan los días soleados.', ans: ['Me', 'encantan', 'los', 'días', 'soleados'], distr: ['encantó', 'nublados', 'noches'], explain: '<b>Encantar</b> works like gustar: the thing is the subject (los días… <i>encantan</i>).' },
    { en: 'If it gets cold, put on your coat.', es: 'Si hace frío, ponte el abrigo.', ans: ['Si', 'hace', 'frío', 'ponte', 'el', 'abrigo'], distr: ['hacía', 'ponerse', 'suéter'], explain: 'Command <b>ponte</b> (ponerse + te) = put it on.' },
    { en: 'There was a rainbow after the rain.', es: 'Después de la lluvia hubo un arcoíris.', ans: ['Después', 'de', 'la', 'lluvia', 'hubo', 'un', 'arcoíris'], distr: ['nevó', 'sol', 'amanecer'], explain: 'Past existential: <b>hubo</b> (there was).' },
    { en: 'It was very windy on the beach.', es: 'En la playa hacía mucho viento.', ans: ['En', 'la', 'playa', 'hacía', 'mucho', 'viento'], distr: ['hace', 'nieve', 'brisa'], explain: 'Past weather description → imperfect: <i>hacía mucho viento</i>.' },
    { en: 'The apartment has three rooms and a small kitchen.', es: 'El departamento tiene tres habitaciones y una cocina pequeña.', ans: ['El', 'departamento', 'tiene', 'tres', 'habitaciones', 'y', 'una', 'cocina', 'pequeña'], distr: ['cuatro', 'grande', 'estación'], explain: 'Counting rooms: <b>habitaciones</b> (Mexican: apartamento).' },
    { en: 'I am going to paint the walls this weekend.', es: 'Voy a pintar las paredes este fin de semana.', ans: ['Voy', 'a', 'pintar', 'las', 'paredes', 'este', 'fin', 'de', 'semana'], distr: ['pinté', 'techo', 'pasado'], explain: '<b>Voy a + infinitive</b> = plan for the weekend.' },
    { en: 'The bathroom is on the second floor.', es: 'El baño está en el segundo piso.', ans: ['El', 'baño', 'está', 'en', 'el', 'segundo', 'piso'], distr: ['primer', 'cocina', 'arriba'], explain: 'Location → <b>estar</b>; ordinal <i>segundo</i>.' },
    { en: 'She is changing the curtains in the living room.', es: 'Ella está cambiando las cortinas del salón.', ans: ['Ella', 'está', 'cambiando', 'las', 'cortinas', 'del', 'salón'], distr: ['cambiaba', 'ventanas', 'comedor'], explain: 'Progressive: <b>está cambiando</b> (happening now).' },
    { en: 'We need to buy a new refrigerator.', es: 'Necesitamos comprar un refrigerador nuevo.', ans: ['Necesitamos', 'comprar', 'un', 'refrigerador', 'nuevo'], distr: ['necesitábamos', 'estufa', 'viejo'], explain: '<b>Necesitar + infinitive</b> = need to…' },
    { en: 'The water is leaking from the sink.', es: 'El agua gotea del lavadero.', ans: ['El', 'agua', 'gotea', 'del', 'lavadero'], distr: ['goteaba', 'grifo', 'techo'], explain: '<b>Gotear</b> = to drip/leak.' },
    { en: 'My parents\' house has a big yard.', es: 'La casa de mis padres tiene un patio grande.', ans: ['La', 'casa', 'de', 'mis', 'padres', 'tiene', 'un', 'patio', 'grande'], distr: ['tenía', 'jardín', 'pequeño'], explain: 'Possession with <b>de</b>: <i>la casa de mis padres</i>.' },
    { en: 'Do not leave the door open.', es: 'No dejes la puerta abierta.', ans: ['No', 'dejes', 'la', 'puerta', 'abierta'], distr: ['dejas', 'cerrada', 'ventana'], explain: 'Negative command (tú): <b>no + subjunctive</b> (no dejes).' },
    { en: 'I would like two tortillas and some guacamole, please.', es: 'Quisiera dos tortillas y algo de guacamole, por favor.', ans: ['Quisiera', 'dos', 'tortillas', 'y', 'algo', 'de', 'guacamole', 'por', 'favor'], distr: ['quiero', 'tres', 'salsa'], explain: '<b>Quisiera</b> (conditional) = the polite "I would like".' },
    { en: 'This beef is very tender.', es: 'Este res está muy tierno.', ans: ['Este', 'res', 'está', 'muy', 'tierno'], distr: ['es', 'duro', 'pollo'], explain: 'State of the food → <b>estar</b>: está tierno.' },
    { en: 'Do you have fresh lemons?', es: '¿Tienen limones frescos?', ans: ['Tienen', 'limones', 'frescos'], distr: ['vendieron', 'naranjas', 'secos'], explain: 'Polite shop question: <b>¿Tienen…?</b>' },
    { en: 'She is boiling eggs for breakfast.', es: 'Ella está hirviendo huevos para el desayuno.', ans: ['Ella', 'está', 'hirviendo', 'huevos', 'para', 'el', 'desayuno'], distr: ['horneando', 'almuerzo', 'cena'], explain: '<b>Hervir</b> = to boil; progressive form.' },
    { en: 'We are chopping onions in the kitchen.', es: 'Estamos picando cebollas en la cocina.', ans: ['Estamos', 'picando', 'cebollas', 'en', 'la', 'cocina'], distr: ['cortaba', 'patatas', 'comedor'], explain: '<b>Picar</b> = to chop (food).' },
    { en: 'The dessert is too sweet.', es: 'El postre está demasiado dulce.', ans: ['El', 'postre', 'está', 'demasiado', 'dulce'], distr: ['es', 'amargo', 'bebida'], explain: '<b>Demasiado</b> = too (much); state → estar.' },
    { en: 'I am only drinking juice, no soda.', es: 'Solo estoy tomando jugo, nada de refresco.', ans: ['Solo', 'estoy', 'tomando', 'jugo', 'nada', 'de', 'refresco'], distr: ['tomaba', 'leche', 'té'], explain: '<b>Nada de + noun</b> = none of…' },
    { en: 'Let us set the table before dinner.', es: 'Pongamos la mesa antes de la cena.', ans: ['Pongamos', 'la', 'mesa', 'antes', 'de', 'la', 'cena'], distr: ['ponemos', 'almuerzo', 'después'], explain: '<b>Pongamos</b> = let\'s (nosotros subjunctive).' },
    { en: 'Turn left at the traffic light and go straight.', es: 'Gira a la izquierda en el semáforo y sigue derecho.', ans: ['Gira', 'a', 'la', 'izquierda', 'en', 'el', 'semáforo', 'y', 'sigue', 'derecho'], distr: ['derecha', 'detente', 'plaza'], explain: 'Giving directions: <b>gira / sigue derecho</b> (commands).' },
    { en: 'The metro closes at eleven at night.', es: 'El metro cierra a las once de la noche.', ans: ['El', 'metro', 'cierra', 'a', 'las', 'once', 'de', 'la', 'noche'], distr: ['abre', 'medianoche', 'autobús'], explain: 'Schedules → present tense: <i>cierra a las once</i>.' },
    { en: 'I parked in front of the hospital.', es: 'Me estacioné frente al hospital.', ans: ['Me', 'estacioné', 'frente', 'al', 'hospital'], distr: ['estacionaba', 'iglesia', 'dentro'], explain: 'Reflexive <b>estacionarse</b> + preterite (it happened).' },
    { en: 'There is a lot of traffic on the highway.', es: 'Hay mucho tráfico en la autopista.', ans: ['Hay', 'mucho', 'tráfico', 'en', 'la', 'autopista'], distr: ['pequeño', 'carretera', 'camino'], explain: '<b>Hay</b> for existing traffic (there is…).' },
    { en: 'Where can I get a map of the city?', es: '¿Dónde puedo conseguir un mapa de la ciudad?', ans: ['Dónde', 'puedo', 'conseguir', 'un', 'mapa', 'de', 'la', 'ciudad'], distr: ['ver', 'pueblo', 'carta'], explain: '<b>Conseguir</b> = to get/obtain.' },
    { en: 'My neighbor drives a pickup truck.', es: 'Mi vecino maneja una camioneta.', ans: ['Mi', 'vecino', 'maneja', 'una', 'camioneta'], distr: ['manejaba', 'carro', 'moto'], explain: 'Mexican Spanish: <b>manejar</b> (not <i>conducir</i>).' },
    { en: 'You have to cross at the crosswalk.', es: 'Tienes que cruzar en el paso peatonal.', ans: ['Tienes', 'que', 'cruzar', 'en', 'el', 'paso', 'peatonal'], distr: ['cruzas', 'acera', 'calle'], explain: '<b>Tener que + infinitive</b> = to have to.' },
    { en: 'This neighborhood is very quiet.', es: 'Este barrio es muy tranquilo.', ans: ['Este', 'barrio', 'es', 'muy', 'tranquilo'], distr: ['ruidoso', 'plaza', 'estupendo'], explain: 'Permanent quality → <b>ser</b>: es tranquilo.' },
    { en: 'How much does this shirt cost?', es: '¿Cuánto cuesta esta camisa?', ans: ['Cuánto', 'cuesta', 'esta', 'camisa'], distr: ['costaba', 'falda', 'vale'], explain: 'Price: <b>¿Cuánto cuesta…?</b>' },
    { en: 'Is the price on the tag?', es: '¿Está el precio en la etiqueta?', ans: ['Está', 'el', 'precio', 'en', 'la', 'etiqueta'], distr: ['estaba', 'ticket', 'local'], explain: 'Location of information → <b>¿Está…?</b>' },
    { en: 'I would like a twenty percent discount on the total.', es: 'Quisiera un descuento del veinte por ciento en el total.', ans: ['Quisiera', 'un', 'descuento', 'del', 'veinte', 'por', 'ciento', 'en', 'el', 'total'], distr: ['incremento', 'treinta', 'precio'], explain: 'Percentages: <b>veinte por ciento</b> (spoken form).' },
    { en: 'Do I pay in cash or by card?', es: '¿Pago en efectivo o con tarjeta?', ans: ['Pago', 'en', 'efectivo', 'o', 'con', 'tarjeta'], distr: ['pagué', 'monedas', 'comprobante'], explain: 'Payment: <b>en efectivo / con tarjeta</b>.' },
    { en: 'The store will exchange it if you bring the receipt.', es: 'La tienda lo cambia si traes la factura.', ans: ['La', 'tienda', 'lo', 'cambia', 'si', 'traes', 'la', 'factura'], distr: ['cambió', 'recibo', 'ropa'], explain: 'Present for a real condition: <b>si + present</b>.' },
    { en: 'I am only looking, thank you.', es: 'Solo estoy mirando, gracias.', ans: ['Solo', 'estoy', 'mirando', 'gracias'], distr: ['miraba', 'disculpé', 'pago'], explain: 'Shop formula: <b>estoy mirando</b> = I\'m just looking.' },
    { en: 'Does this phone have a warranty?', es: '¿Este teléfono tiene garantía?', ans: ['Este', 'teléfono', 'tiene', 'garantía'], distr: ['tenía', 'precio', 'computadora'], explain: '<b>Tener garantía</b> = to have a warranty.' },
    { en: 'The delivery of my package was delayed.', es: 'La entrega de mi paquete se retrasó.', ans: ['La', 'entrega', 'de', 'mi', 'paquete', 'se', 'retrasó'], distr: ['llegó', 'sobre', 'tiempo'], explain: '<b>Retrasarse</b> = to be delayed (preterite: it happened).' },
    { en: 'I wake up at six every day.', es: 'Me despierto a las seis todos los días.', ans: ['Me', 'despierto', 'a', 'las', 'seis', 'todos', 'los', 'días'], distr: ['dormí', 'siete', 'noches'], explain: 'Routine → present: <b>me despierto</b>.' },
    { en: 'I took a nap after lunch.', es: 'Dormí una siesta después del almuerzo.', ans: ['Dormí', 'una', 'siesta', 'después', 'del', 'almuerzo'], distr: ['desperté', 'cena', 'antes'], explain: 'Finished action → preterite: <i>dormí</i>; <b>la siesta</b> (Mexican nap).' },
    { en: 'She puts on makeup before work.', es: 'Ella se maquilla antes de ir al trabajo.', ans: ['Ella', 'se', 'maquilla', 'antes', 'de', 'ir', 'al', 'trabajo'], distr: ['maquillaba', 'casa', 'después'], explain: 'Reflexive <b>maquillarse</b> + <i>antes de + infinitive</i>.' },
    { en: 'Do you want to make a plan for Saturday?', es: '¿Quieres hacer un plan para el sábado?', ans: ['Quieres', 'hacer', 'un', 'plan', 'para', 'el', 'sábado'], distr: ['querías', 'domingo', 'fiesta'], explain: '<b>¿Quieres + infinitive?</b> = do you want to…' },
    { en: 'My mother has run a small shop for ten years.', es: 'Mi madre lleva diez años con un local pequeño.', ans: ['Mi', 'madre', 'lleva', 'diez', 'años', 'con', 'un', 'local', 'pequeño'], distr: ['tiene', 'grandes', 'tienda'], explain: '<b>Llevar + time</b> = to have been doing (for X years).' },
    { en: 'He is shaving before the meeting.', es: 'Se está afeitando antes de la reunión.', ans: ['Se', 'está', 'afeitando', 'antes', 'de', 'la', 'reunión'], distr: ['peinaba', 'clase', 'trabajo'], explain: 'Reflexive progressive: <b>se está afeitando</b>.' },
    { en: 'What are your plans for the weekend?', es: '¿Cuáles son tus planes para el fin de semana?', ans: ['Cuáles', 'son', 'tus', 'planes', 'para', 'el', 'fin', 'de', 'semana'], distr: ['dónde', 'vacaciones', 'mañana'], explain: 'Plural question word: <b>¿Cuáles son…?</b>' },
    { en: 'I will give you the gift on your birthday.', es: 'Te doy el regalo en tu cumpleaños.', ans: ['Te', 'doy', 'el', 'regalo', 'en', 'tu', 'cumpleaños'], distr: ['di', 'regalos', 'aniversario'], explain: 'Clitic before the verb: <b>te doy</b>.' },
    { en: 'There is a river behind the park.', es: 'Hay un río detrás del parque.', ans: ['Hay', 'un', 'río', 'detrás', 'del', 'parque'], distr: ['bosque', 'frente', 'lago'], explain: '<b>Detrás de</b> = behind (hay un río detrás del…).' },
    { en: 'We are planting trees in the neighborhood.', es: 'Estamos plantando árboles en el barrio.', ans: ['Estamos', 'plantando', 'árboles', 'en', 'el', 'barrio'], distr: ['plantábamos', 'flores', 'calle'], explain: 'Progressive + <b>plantar árboles</b>.' },
    { en: 'The sea was very calm yesterday.', es: 'El mar estaba muy calmado ayer.', ans: ['El', 'mar', 'estaba', 'muy', 'calmado', 'ayer'], distr: ['agitado', 'sol', 'hoy'], explain: 'Temporary state yesterday → <b>imperfect</b> (estaba calmado).' },
    { en: 'Birds sing at dawn.', es: 'Los pájaros cantan al amanecer.', ans: ['Los', 'pájaros', 'cantan', 'al', 'amanecer'], distr: ['cantaban', 'mediodía', 'gallinas'], explain: 'General truth → present: <i>cantan al amanecer</i>.' },
    { en: 'The forest is full of flowers this season.', es: 'El bosque está lleno de flores esta temporada.', ans: ['El', 'bosque', 'está', 'lleno', 'de', 'flores', 'esta', 'temporada'], distr: ['seco', 'hojas', 'invierno'], explain: '<b>Estar lleno de</b> = to be full of…' },
    { en: 'The mountain is very high.', es: 'La montaña es muy alta.', ans: ['La', 'montaña', 'es', 'muy', 'alta'], distr: ['baja', 'cumbre', 'pequeña'], explain: 'Permanent quality → <b>ser</b>: es alta.' },
    { en: 'There is a beach near the island.', es: 'Hay una playa cerca de la isla.', ans: ['Hay', 'una', 'playa', 'cerca', 'de', 'la', 'isla'], distr: ['lejos', 'montaña', 'río'], explain: '<b>Cerca de</b> = near; <i>hay</i> = there is.' },
    { en: 'We should protect the environment.', es: 'Debemos proteger el medio ambiente.', ans: ['Debemos', 'proteger', 'el', 'medio', 'ambiente'], distr: ['protegemos', 'desierto', 'contaminar'], explain: '<b>Deber + infinitive</b> = should; <i>el medio ambiente</i>.' },
    { en: 'I wish it were warmer in winter.', es: 'Ojalá hiciera más calor en invierno.', ans: ['Ojalá', 'hiciera', 'más', 'calor', 'en', 'invierno'], distr: ['hace', 'frío', 'verano'], explain: '<b>Ojalá + imperfect subjunctive</b> = I wish it were…' },
    { en: 'As long as it does not rain, we will go to the beach.', es: 'Siempre que no llueva, iremos a la playa.', ans: ['Siempre', 'que', 'no', 'llueva', 'iremos', 'a', 'la', 'playa'], distr: ['llueve', 'iríamos', 'montaña'], explain: '<b>Siempre que + subjunctive</b> = as long as.' },
    { en: 'I had not seen the sea in ten years.', es: 'No había visto el mar en diez años.', ans: ['No', 'había', 'visto', 'el', 'mar', 'en', 'diez', 'años'], distr: ['veía', 'lago', 'cinco'], explain: '<b>Pluperfect</b>: no había visto = I had not seen.' },
    { en: 'When I got home, it was already raining.', es: 'Cuando llegué a casa, ya estaba lloviendo.', ans: ['Cuando', 'llegué', 'a', 'casa', 'ya', 'estaba', 'lloviendo'], distr: ['llegaba', 'lluvia', 'tarde'], explain: 'Interrupted scene: <b>preterite (llegué) + imperfect progressive (estaba lloviendo)</b>.' },
    { en: 'I hope the new apartment is closer to work.', es: 'Espero que el nuevo departamento esté más cerca del trabajo.', ans: ['Espero', 'que', 'el', 'nuevo', 'departamento', 'esté', 'más', 'cerca', 'del', 'trabajo'], distr: ['está', 'lejos', 'casa'], explain: 'Hope → <b>espero que + subjunctive</b> (esté).' },
    { en: 'I do not think it will snow this year.', es: 'No creo que nieve este año.', ans: ['No', 'creo', 'que', 'nieve', 'este', 'año'], distr: ['nieva', 'nevó', 'verano'], explain: 'Negated creer → <b>subjunctive</b>: que nieve.' },
    { en: 'If I had known about the storm, I would have stayed home.', es: 'Si hubiera sabido de la tormenta, me habría quedado en casa.', ans: ['Si', 'hubiera', 'sabido', 'de', 'la', 'tormenta', 'me', 'habría', 'quedado', 'en', 'casa'], distr: ['sabía', 'quedé', 'lluvia'], explain: 'Past unreal: <b>si hubiera sabido… me habría quedado</b>.' },
    { en: 'She would have bought the dress if it had been cheaper.', es: 'La habría comprado si hubiera sido más barata.', ans: ['La', 'habría', 'comprado', 'si', 'hubiera', 'sido', 'más', 'barata'], distr: ['compré', 'cara', 'teléfono'], explain: 'Conditional perfect + past unreal condition.' },
    { en: 'It is the first time I have cooked for my family.', es: 'Es la primera vez que cocino para mi familia.', ans: ['Es', 'la', 'primera', 'vez', 'que', 'cocino', 'para', 'mi', 'familia'], distr: ['cociné', 'padres', 'mesa'], explain: '<b>La primera vez que + present</b>.' },
    { en: 'Before I moved, I used to walk to work.', es: 'Antes de mudarme, caminaba al trabajo.', ans: ['Antes', 'de', 'mudarme', 'caminaba', 'al', 'trabajo'], distr: ['mudé', 'oficina', 'carro'], explain: '<b>Antes de + reflexive infinitive</b>; <i>caminaba</i> = used to walk (habitual past).' },
    { en: 'She is tall, thin, with dark hair.', es: 'Ella es alta, delgada y de pelo castaño.', ans: ['Ella', 'es', 'alta', 'delgada', 'y', 'de', 'pelo', 'castaño'], distr: ['baja', 'rubio', 'rubia'], explain: 'Appearance traits → <b>ser</b> + adjectives that agree.' },
    { en: 'My brother is very responsible and hardworking.', es: 'Mi hermano es muy responsable y trabajador.', ans: ['Mi', 'hermano', 'es', 'muy', 'responsable', 'y', 'trabajador'], distr: ['perezoso', 'hermana', 'simpático'], explain: 'Personality → <b>ser</b> (permanent trait).' },
    { en: 'I feel nervous before the interview.', es: 'Me siento nerviosa antes de la entrevista.', ans: ['Me', 'siento', 'nerviosa', 'antes', 'de', 'la', 'entrevista'], distr: ['nervioso', 'clase', 'trabajo'], explain: '<b>sentirse + adjective</b> (agree with the speaker: nerviosa).' },
    { en: 'He looks tired, but he is happy.', es: 'Parece cansado, pero está contento.', ans: ['Parece', 'cansado', 'pero', 'está', 'contento'], distr: ['triste', 'enojado', 'feliz'], explain: '<b>Parecer + adjective</b>; mood → <i>estar contento</i>.' },
    { en: 'She is the youngest in the family.', es: 'Es la más joven de la familia.', ans: ['Es', 'la', 'más', 'joven', 'de', 'la', 'familia'], distr: ['mayor', 'padre', 'vecina'], explain: 'Superlative: <b>la más + adjective + de</b>.' },
    { en: 'I am embarrassed in front of new people.', es: 'Me siento avergonzado frente a gente nueva.', ans: ['Me', 'siento', 'avergonzado', 'frente', 'a', 'gente', 'nueva'], distr: ['avergonzada', 'conocida', 'familia'], explain: '<b>Frente a</b> = in front of.' },
    { en: 'My boss is strict but fair.', es: 'Mi jefe es estricto pero justo.', ans: ['Mi', 'jefe', 'es', 'estricto', 'pero', 'justo'], distr: ['flojo', 'injusto', 'jefa'], explain: 'Two personality adjectives joined with <b>pero</b>.' },
    { en: 'They are a very kind couple.', es: 'Son una pareja muy amable.', ans: ['Son', 'una', 'pareja', 'muy', 'amable'], distr: ['grosera', 'familia', 'simpática'], explain: '<b>La pareja</b> is singular: son <i>una</i> pareja amable.' },
    { en: 'I am working from home this month.', es: 'Trabajo desde casa este mes.', ans: ['Trabajo', 'desde', 'casa', 'este', 'mes'], distr: ['oficina', 'año', 'semana'], explain: '<b>Trabajar desde casa</b> = to work from home.' },
    { en: 'The computer crashed and I lost the document.', es: 'La computadora se cayó y perdí el documento.', ans: ['La', 'computadora', 'se', 'cayó', 'y', 'perdí', 'el', 'documento'], distr: ['falló', 'encontré', 'correo'], explain: '<b>Caerse</b> (of machines) = to crash; both actions in the preterite.' },
    { en: 'I will pay the bi-weekly salary this Friday.', es: 'Pagaré la quincena este viernes.', ans: ['Pagaré', 'la', 'quincena', 'este', 'viernes'], distr: ['pagué', 'semana', 'lunes'], explain: 'Future: <b>pagaré</b>; <i>la quincena</i> (Mexican bi-weekly pay).' },
    { en: 'My sister studies law at the university.', es: 'Mi hermana estudia derecho en la universidad.', ans: ['Mi', 'hermana', 'estudia', 'derecho', 'en', 'la', 'universidad'], distr: ['medicina', 'licenciatura', 'colega'], explain: 'Present for a current situation: <i>estudia derecho</i>.' },
    { en: 'He is asking for a day off to take care of his mother.', es: 'Pide un permiso para cuidar a su madre.', ans: ['Pide', 'un', 'permiso', 'para', 'cuidar', 'a', 'su', 'madre'], distr: ['pidió', 'padre', 'trabajo'], explain: '<b>Para + infinitive</b> = in order to; <i>cuidar a</i> (with a for people).' },
    { en: 'The library closes at eight in the evening.', es: 'La biblioteca cierra a las ocho de la tarde.', ans: ['La', 'biblioteca', 'cierra', 'a', 'las', 'ocho', 'de', 'la', 'tarde'], distr: ['abre', 'mañana', 'noche'], explain: 'Schedules → present: <i>cierra a las ocho</i>.' },
    { en: 'I will leave my cell phone on the desk.', es: 'Dejaré mi celular sobre el escritorio.', ans: ['Dejaré', 'mi', 'celular', 'sobre', 'el', 'escritorio'], distr: ['dejé', 'teléfono', 'mesa'], explain: 'Future <b>dejaré</b>; Mexican Spanish: <i>celular</i>.' },
    { en: 'I am going to fix the lamp this weekend.', es: 'Voy a arreglar la lámpara este fin de semana.', ans: ['Voy', 'a', 'arreglar', 'la', 'lámpara', 'este', 'fin', 'de', 'semana'], distr: ['arreglé', 'lámparas', 'pasado'], explain: '<b>Arreglar</b> = to fix; <i>ir a + infinitive</i> for plans.' },
  ];

  const B1G = [
    { id: 'g-b1-1', en: 'I am used to waking up early.', correct: 'Estoy acostumbrado a levantarme temprano.', wrongs: ['Estoy acostumbrado de levantarme temprano.', 'Estoy acostumbrado levantarme temprano.'], explain: '<b>Acostumbrado a + infinitive</b> (with <i>a</i>, not <i>de</i>).' },
    { id: 'g-b1-2', en: 'She is thinking about changing jobs.', correct: 'Está pensando en cambiar de trabajo.', wrongs: ['Está pensando cambiar de trabajo.', 'Está pensando sobre cambiar de trabajo.'], explain: '<b>Pensar en + infinitive</b> = to be thinking about doing.' },
    { id: 'g-b1-3', en: 'I am angry with you for lying.', correct: 'Estoy molesto contigo por mentir.', wrongs: ['Estoy molesto con tú por mentir.', 'Estoy molesto con vosotros por mentir.'], explain: 'Prepositions always take the <b>oblique</b> form: <i>contigo</i>, never <i>con tú</i>.' },
    { id: 'g-b1-4', en: 'I have been working here for three months.', correct: 'Llevo tres meses trabajando aquí.', wrongs: ['Llevo tres meses trabajo aquí.', 'Trabajo tres meses aquí desde.'], explain: 'Duration up to now: <b>llevo + time + -ing</b>.' },
    { id: 'g-b1-5', en: 'I miss my grandmother a lot.', correct: 'Echo de menos a mi abuela mucho.', wrongs: ['Extraño de mi abuela mucho.', 'Eco de menos a mi abuela mucho.'], explain: '<b>Echar de menos + a</b> (with a for people).' },
    { id: 'g-b1-6', en: 'She is proud of her work.', correct: 'Está orgullosa de su trabajo.', wrongs: ['Está orgullosa con su trabajo.', 'Está orgullosa del su trabajo.'], explain: '<b>Orgulloso/a de + noun</b> = proud of.' },
    { id: 'g-b1-7', en: 'I regret not having told the truth.', correct: 'Me arrepiento de no haber dicho la verdad.', wrongs: ['Me arrepiento de no decir la verdad.', 'Arrepiento de no haber decir la verdad.'], explain: 'Past regret: <b>arrepentirse de + haber + participle</b>.' },
    { id: 'g-b1-8', en: 'The cost of living is going up.', correct: 'El costo de la vida está subiendo.', wrongs: ['El costo de la vida está suben.', 'El coste de la vidas está subiendo.'], explain: '<b>El costo de la vida</b> = cost of living (singular!); progressive <i>está subiendo</i>.' },
    { id: 'g-b1-9', en: 'I am looking for a better job.', correct: 'Estoy buscando un mejor trabajo.', wrongs: ['Estoy buscando para un mejor trabajo.', 'Busco buscando un mejor trabajo.'], explain: '<b>Buscar + object directly</b> (no <i>para</i>).' },
    { id: 'g-b1-10', en: 'I am afraid of making a mistake.', correct: 'Tengo miedo de cometer un error.', wrongs: ['Tengo miedo de cometer una error.', 'Tengo miedo para cometer un error.'], explain: '<b>Tener miedo de + infinitive</b>; <i>error</i> is masculine.' },
    { id: 'g-b1-11', en: 'I am used to working in the morning.', correct: 'Estoy acostumbrado a trabajar por las mañanas.', wrongs: ['Estoy acostumbrado a trabajar por las mañana.', 'Soy acostumbrado a trabajar por las mañanas.'], explain: '<b>Acostumbrado a + infinitive</b>; with a routine, <i>por las</i> + plural.' },
    { id: 'g-b1-12', en: 'I have been here since you arrived.', correct: 'Llevo aquí desde que llegaste.', wrongs: ['Llevo aquí desde cuando llegaste.', 'Desde que llegué, llevo aquí.'], explain: '<b>Desde que + indicative</b> for a real past fact.' },
    { id: 'g-b1-13', en: 'You should have told me yesterday.', correct: 'Deberías habérmelo dicho ayer.', wrongs: ['Deberías lo dijiste ayer.', 'Deberías me lo dijiste ayer.'], explain: '<b>Deberías + haber + participle</b>: deberías habérmelo dicho.' },
    { id: 'g-b1-14', en: 'It is possible that it will rain tomorrow.', correct: 'Es posible que llueva mañana.', wrongs: ['Es posible que llueve mañana.', 'Es posible que llovía mañana.'], explain: '<b>Es posible que + subjunctive</b>.' },
    { id: 'g-b1-15', en: 'The book you lent me is wonderful.', correct: 'El libro que me prestaste es maravilloso.', wrongs: ['El libro el que me lo prestaste es maravilloso.', 'El libro cual me prestaste es maravilloso.'], explain: 'Relative <b>que</b> without any extra pronoun (no <i>el que… lo</i>).' },
    { id: 'g-b1-16', en: 'I would rather stay home today.', correct: 'Hoy prefiero quedarme en casa.', wrongs: ['Hoy prefiero a quedarme en casa.', 'Hoy prefiero quedándome en casa.'], explain: '<b>Preferir + infinitive</b>, without <i>a</i>.' },
    { id: 'g-b1-17', en: 'He arrived before I started.', correct: 'Llegó antes de que yo empezara.', wrongs: ['Llegó antes de que yo empecé.', 'Llegó antes de yo empezar.'], explain: '<b>Antes de que + subjunctive</b>.' },
    { id: 'g-b1-18', en: 'In any case, I am not going.', correct: 'De todos modos, no voy a ir.', wrongs: ['De todos modos, no voy ir.', 'De todos modos, no vengo a ir.'], explain: '<b>De todos modos</b> = anyway; <i>ir a + infinitive</i>.' },
    { id: 'g-b1-19', en: 'I don\'t think it will rain.', correct: 'No creo que vaya a llover.', wrongs: ['No creo que va a llover.', 'No creo que va llover.'], explain: 'Negated creer + que → <b>subjunctive</b> (vaya a llover).' },
    { id: 'g-b1-20', en: 'The fact is that he is not coming.', correct: 'Lo cierto es que no viene.', wrongs: ['Lo cierto es que no va venir.', 'Lo cierto es que no viniendo.'], explain: '<b>Lo + adjective + es que…</b> = "the truth is that…"' },
    { id: 'g-b1-21', en: 'We had already left when she arrived.', correct: 'Ya nos habíamos ido cuando ella llegó.', wrongs: ['Ya nos hemos ido cuando ella llegó.', 'Ya estábamos nos ido cuando ella llegó.'], explain: 'Pluperfect = **había + participle** for the action that happened first.' },
    { id: 'g-b1-22', en: 'I had not seen that film before.', correct: 'No había visto esa película antes.', wrongs: ['No he visto esa película antes.', 'No vi había esa película antes.'], explain: '**No había + participle + antes** — the reference point is in the past.' },
    { id: 'g-b1-23', en: 'Tell me (it), please.', correct: 'Dímelo, por favor.', wrongs: ['Dime lo, por favor.', 'Dilo me, por favor.'], explain: 'Clitics fuse: di + me + lo = **dímelo** (accent shifts).' },
    { id: 'g-b1-24', en: 'Can you tell me (it)?', correct: '¿Me lo dices?', wrongs: ['¿Lo me dices?', '¿Me dice lo?'], explain: 'Order with a conjugated verb: **me lo + verb** (me before lo).' },
    { id: 'g-b1-25', en: 'Write it down on the list.', correct: 'Escríbelo en la lista.', wrongs: ['Escribe lo en la lista.', 'Escríbelo en las lista.'], explain: 'Affirmative command + fused clitics + accent: **escríbelo**.' },
    { id: 'g-b1-26', en: 'I am nervous.', correct: 'Estoy nervioso.', wrongs: ['Soy nervioso.', 'Estoy ser nervioso.'], explain: 'Emotional states use **estar**: estoy nervioso.' },
    { id: 'g-b1-27', en: 'She is lazy.', correct: 'Ella es perezosa.', wrongs: ['Ella está perezosa.', 'Ella es perezoso.'], explain: 'Personality traits use **ser** — and it agrees: perezosa (feminine).' },
    { id: 'g-b1-28', en: 'He seems tired.', correct: 'Parece cansado.', wrongs: ['Parecen cansado.', 'Parece que está ser cansado.'], explain: '**Parecer + adjective** directly (parece cansado).' },
    { id: 'g-b1-29', en: 'She asked where I lived.', correct: 'Ella preguntó dónde vivía.', wrongs: ['Ella preguntó ¿dónde vivo?', 'Ella preguntó donde yo vivido.'], explain: 'Reported question: no inversion, no ¿?, and the past shifts (vivía).' },
    { id: 'g-b1-30', en: 'Do you know if he is coming?', correct: '¿Sabes si viene?', wrongs: ['¿Sabes que viene?', '¿Sabes ¿viene?'], explain: 'Reported yes/no questions use **si** (not <i>que</i>), without ¿?.' },
    { id: 'g-b1-31', en: 'I will go, unless it rains.', correct: 'Iré, a menos que llueva.', wrongs: ['Iré, a menos que llueve.', 'Iré, a menos que lluvia.'], explain: '**A menos que** = unless → subjunctive (llueva).' },
    { id: 'g-b1-32', en: 'In case you need it, here is the number.', correct: 'En caso de que lo necesites, aquí tienes el número.', wrongs: ['En caso de que lo necesitas, aquí tienes el número.', 'En caso de que lo necesites, aquí tienen el número.'], explain: '**En caso de que + subjunctive** = in case…' },
    { id: 'g-b1-33', en: 'Even if I am busy, I will come.', correct: 'Aunque esté ocupado, voy a venir.', wrongs: ['Aunque estoy ocupado, voy a venir.', 'Aunque estaré ocupado, voy a venir.'], explain: '**Aunque + subjunctive** for a doubtful/future concession (esté).' },
    { id: 'g-b1-34', en: 'It is fine, as long as you let me know.', correct: 'Está bien, siempre que me avises.', wrongs: ['Está bien, siempre que me avisas.', 'Está bien, siempre que me aviso.'], explain: '**Siempre que + subjunctive** as a condition (avises).' },
    { id: 'g-b1-35', en: 'I hope you pass the exam.', correct: 'Ojalá apruebes el examen.', wrongs: ['Ojalá apruebas el examen.', 'Ojalá apruebo el examen.'], explain: '**Ojalá + subjunctive** for a wish (apruebes).' },
    { id: 'g-b1-36', en: 'The book I told you about is interesting.', correct: 'El libro del que te hablé es interesante.', wrongs: ['El libro el cual te hablé es interesante.', 'El libro que te lo hablé es interesante.'], explain: 'Preposition + **el que**: del que te hablé = "that I told you about".' },
    { id: 'g-b1-37', en: 'The story I dreamed about was crazy.', correct: 'La historia de la que soñé era loca.', wrongs: ['La historia el que soñé era loca.', 'La historia que de ella soñé era loca.'], explain: 'Feminine antecedent: **de la que** (de + la + que).' },
    { id: 'g-b1-38', en: 'I gave it to him.', correct: 'Se lo di a él.', wrongs: ['Lo le di a él.', 'Se lo de a él.'], explain: 'Double pronouns: **le + lo → se lo** (le becomes se).' },
    { id: 'g-b1-39', en: 'I want to tell him (it).', correct: 'Quiero decírselo.', wrongs: ['Quiero decir se lo.', 'Quiero decíselo.'], explain: 'Clitics attach to the infinitive: **decírselo** (accent kept).' },
    { id: 'g-b1-40', en: 'I saw him crossing the street.', correct: 'Lo vi cruzando la calle.', wrongs: ['Le vi cruzando la calle.', 'Lo veo cruzado la calle.'], explain: 'With -ndo, the direct object takes **lo/la** (lo vi cruzando).' },
    { id: 'g-b1-41', en: 'Here they speak Spanish.', correct: 'Aquí se habla español.', wrongs: ['Aquí hablan español se.', 'Aquí se hablan español.'], explain: 'Impersonal **se + singular verb** (se habla), the topic comes after.' },
    { id: 'g-b1-42', en: 'I am going to move next month.', correct: 'Voy a mudarme el mes que viene.', wrongs: ['Voy mudo el mes que viene.', 'Voy a mudarme al mes que venía.'], explain: 'Near-future plan: **ir a + infinitive**; clitic on the infinitive (mudarme).' },
    { id: 'g-b1-43', en: 'I am looking for a job.', correct: 'Estoy buscando trabajo.', wrongs: ['Estoy buscando a trabajo.', 'Estoy buscar trabajo.'], explain: '**Estar + -ing**; <i>trabajo</i> with no article ("job" in general).' },
    { id: 'g-b1-44', en: 'It has been two years since I graduated.', correct: 'Hace dos años que me gradué.', wrongs: ['Hace dos años que me gradúo.', 'Es dos años que me gradué.'], explain: '**Hace + time + que + preterite** = it has been… since I…' },
    { id: 'g-b1-45', en: 'I want a little more water.', correct: 'Quiero un poco más de agua.', wrongs: ['Quiero un poco más agua.', 'Quiero un poco más de las agua.'], explain: '**Un poco de + noun** (always with <i>de</i>); agua is singular.' },
  ];


